  const label=document.createElement('button');label.className='furniture-label';label.dataset.furniture=item.kind;label.dataset.furnitureId=item.id;label.textContent=item.worldLabel||(item.kind==='seat'?'坐下':item.kind==='canopy'?'纱帐':item.kind==='bed'?'躺下':item.kind==='bath'?'泡澡':'换装');label.setAttribute('aria-label',item.name+' · '+furnitureAction(item));label.hidden=true;label.onclick=()=>requestFurniture(item);$('furniture-labels').append(label);furnitureLabels.push({item,label});
