const projectPoint=(p,el)=>{const v=p.clone().project(camera);el.style.left=(v.x*.5+.5)*innerWidth+'px';el.style.top=(-v.y*.5+.5)*innerHeight+'px';return v.z<1&&Math.abs(v.x)<1.1&&Math.abs(v.y)<1.1;};
function updateLabels(){if(mode==='globe'){globe.markers.forEach(m=>{const el=globeLabels.get(m.id);if(!el)return;const p=m.anchor.clone().multiplyScalar(1.13).applyMatrix4(globe.group.matrixWorld);const facing=p.clone().normalize().dot(camera.position.clone().normalize());el.hidden=facing<.12||!projectPoint(p,el);});}else{npcs.forEach(n=>{const p=n.root.position.clone().add(new THREE.Vector3(0,n.root.userData.labelHeight??(n.station.npcAction==='kotatsu'&&!n.walking?1.65:2.55),0));n.label.hidden=!n.root.visible||roofShown||!projectPoint(p,n.label)||n.root.position.distanceTo(player.root.position)>10||Math.abs(n.root.position.y-player.root.position.y)>2||cameraDistanceToObstacle(camera.position,p,cameraSolids,0)<camera.position.distanceTo(p)-.3;});}}
function updateFurnitureLabels(){if(mode!=='lot'||!player)return;let shown=0;for(const {item,label}of [...furnitureLabels].sort((a,b)=>pointDistance(a.item)-pointDistance(b.item))){const p=furniture.markerPoint(item);label.hidden=!!(item.bathPose&&(bathTransition?.item.poolId||seated?.poolId||seated?.id)===item.id)||roofShown||outfitPreview.state().open||Math.abs(item.position[1]-player.root.position.y)>.8||pointDistance(item)>14||shown>=6||!furniture.isVisible(item,camera.position,p,cameraSolids)||!projectPoint(p,label);if(!label.hidden)shown++;}function pointDistance(item){return Math.hypot(item.center[0]-player.root.position.x,item.center[2]-player.root.position.z);}}

